<?php
declare(strict_types=1);
function el457Catalog():array {static $items;return $items??=json_decode(file_get_contents(__DIR__.'/electronics457-catalog.json'),true,64,JSON_THROW_ON_ERROR)['items'];}
function el457Types():array{return ['camera'=>'Fototoestellen','video'=>'VHS-spelers','dvd'=>'DVD-spelers','tv'=>'Televisies','computer'=>'Computers','laptop'=>'Laptops','walkman'=>'Walkmans','discman'=>'Discmans','stereo'=>'Stereosets & platenspelers'];}
function el457Damage():array{return ['housing'=>['Behuizing',25],'working'=>['Werking',35],'screen'=>['Display / bediening',15],'accessories'=>['Accessoires',15],'packaging'=>['Verpakking',10]];}
function el457Attribution(array $m):string{$a=$m['art'];return '<small class="vm415-credit"><a href="'.h($a['source']).'" target="_blank" rel="noopener">Foto: '.h($a['artist']?:'zie bron').'</a> · <a href="'.h($a['license_url']).'" target="_blank" rel="noopener">'.h($a['license']).'</a><br>'.h($a['changes']).'<br>Verzamelklasse en punten: VCollector-spelwaarden.</small>';}
function el457Details(array $m):string{return '<dl><dt>Merk / model</dt><dd>'.h($m['title']).'</dd><dt>Soort</dt><dd>'.h(el457Types()[$m['category']]??'Elektronica').'</dd><dt>Cataloguspunten</dt><dd>'.(int)$m['points'].' · spelwaarde, geen taxatie</dd></dl><p>'.h($m['summary457']??'').'</p><p>De conditie van elk virtueel exemplaar wordt apart bepaald.</p>'.el457Attribution($m);}
function el457Art(array $x):string{$m=$x['model'];return '<figure class="el457-art"><a href="'.h($m['art']['image']).'" data-el457-zoom><img src="'.h($m['art']['image']).'" alt="'.h($m['title']).'" width="640" height="480" loading="lazy"></a><figcaption>'.h($m['title']).' · '.(int)$x['grade']['points'].' punten</figcaption>'.el457Attribution($m).'</figure>';}
function el457Menu(string $html):string{
 if(!function_exists('user')||!user()||str_contains($html,'data-el457-menu'))return $html;
 return preg_replace_callback('~(<summary\b[^>]*>\s*(?:<[^>]+>)*\s*Verzamelen.*?</summary>)~isu',fn($m)=>$m[1].'<div data-el457-menu><a href="/index.php?el457=catalog">Elektronica</a><a href="/index.php?el457=mine">Mijn elektronica</a></div>',$html,1)??$html;
}
function el457IsRequest(array $u,string $route):bool{
 if(($_GET['kind']??'')==='electro')return true;
 if($route==='object'&&is_string($_GET['ref']??null)&&preg_match('/^o-[a-f0-9]{32}$/D',$_GET['ref'])){ $o=hbObject325($_GET['ref']);return ($o['design']['media415']['model']['kind']??'')==='electro'; }return false;
}
function el457Page(array $u,string $route):string{
 $s='<link rel="stylesheet" href="/assets/electronics457.css?v=457"><script defer src="/assets/electronics457.js?v=457"></script><section class="el457"><header><div><small>VCOLLECTOR · VERZAMELEN</small><h1>Verzamelelektronica</h1></div><nav><a href="/index.php?el457=catalog">Catalogus</a><a href="/index.php?el457=mine">Mijn exemplaren</a>'.(($u['role']??'')==='owner'?'<a href="/index.php?el457=admin">Beheer</a>':'').'</nav></header>';
 if(!empty($_SESSION['el457notice'])){$s.='<p role="status">'.h($_SESSION['el457notice']).'</p>';unset($_SESSION['el457notice']);}
 if($route==='object'){$o=hbObject325((string)$_GET['ref']);$x=$o['design']['media415']??null;if(($x['model']['kind']??'')!=='electro')fail('Geen elektronica-exemplaar.');if(($_SESSION['vm415opened']??'')===$o['ref']){$s.='<p role="status" class="el457-reveal">Je schatkist is geopend: '.h($o['name']).'!</p>';unset($_SESSION['vm415opened']);}$s.=el457Art($x).'<p><b>'.h($x['grade']['grade']).' · '.(float)$x['grade']['condition'].'% · '.(int)$x['grade']['points'].' punten</b></p><details><summary>Conditie per onderdeel</summary><dl>';foreach(el457Damage() as $key=>[$label,$weight])$s.='<dt>'.h($label).'</dt><dd>Niveau '.(int)$x['damage'][$key].'/6 · '.$weight.'% weging</dd>';$s.='</dl></details>'.el457Details($x['model']).'<a href="/index.php?world=collect&amp;item='.h($o['ref']).'">Verkopen, ruilen en eigendom bekijken</a>';return $s.'</section>';}
 if($route==='admin'){
 if(($u['role']??'')!=='owner')fail('Alleen hoofdbeheer.');$j=vm415Job('electro')['data'];return $s.'<p>'.count(el457Catalog()).' modellen met lokale foto’s. Geen live API-aanvragen.</p><form method="post" action="/index.php?el457=save"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><label>Prijs schatkist (VC)<input name="price" type="number" min="1" max="1000000" required value="'.(int)$j['price'].'"></label><label>Daglimiet<input name="daily" type="number" min="1" max="100" required value="'.(int)$j['daily'].'"></label><label><input type="checkbox" name="enabled" value="1" '.(!empty($j['enabled'])?'checked':'').'> Nieuwe schatkisten beschikbaar</label><button>Opslaan</button></form><p>Uitschakelen behoudt bestaande exemplaren en handel.</p></section>';
 }
 $type=is_string($_GET['type457']??null)?$_GET['type457']:'';if(!isset(el457Types()[$type]))$type='';$search=is_string($_GET['q457']??null)?trim(mb_substr($_GET['q457'],0,80)):'';
 $s.='<details><summary>Hoe werkt elektronica verzamelen?</summary><p>Je ontvangt na aankoop één willekeurig echt model als digitaal verzamelobject. Dubbelen zijn mogelijk. Werking, behuizing, bediening, accessoires en verpakking bepalen de exemplaarpunten. Je kunt exemplaren bewaren, verkopen of ruilen via de bestaande verzamelmarkt. Dit zijn geen fysieke apparaten.</p></details>';
 if($route!=='mine'){
 $j=vm415Job('electro')['data'];$count=(int)(one("SELECT COUNT(*) n FROM go_media415_titles WHERE kind='electro'")['n']??0);
 if(!empty($j['enabled'])&&$count){$nonce=uid();$_SESSION['vm415quotes']??=[];foreach($_SESSION['vm415quotes'] as $n=>$v)if($v['at']<time()-1800)unset($_SESSION['vm415quotes'][$n]);while(count($_SESSION['vm415quotes'])>=10)array_shift($_SESSION['vm415quotes']);$quote=hash('sha256',enc(['electro',$j['price'],$j['enabled'],$j['daily'],$count]));$_SESSION['vm415quotes'][$nonce]=['kind'=>'electro','at'=>time(),'quote'=>$quote];$s.='<details class="el457-buy"><summary>Elektronicaschatkist · '.(int)$j['price'].' VC</summary><p>Eén willekeurig model uit alle '.$count.' modellen, kans per model 1 op '.$count.'. Filters veranderen deze kans niet.</p>'.vc415Form('buy',['kind'=>'electro','nonce'=>$nonce,'quote'=>$quote]).'<label><input type="checkbox" required name="confirm" value="1"> Ik besteed '.(int)$j['price'].' VC.</label><button>Kopen en openen</button></form></details>';}
 else $s.='<p>Nieuwe schatkisten zijn tijdelijk gesloten. Je kunt de catalogus en je exemplaren bekijken.</p>';
 }
 $s.='<form method="get" class="el457-filters"><input type="hidden" name="el457" value="'.($route==='mine'?'mine':'catalog').'"><label>Soort<select name="type457"><option value="">Alle soorten</option>';foreach(el457Types() as $k=>$label)$s.='<option value="'.$k.'" '.($type===$k?'selected':'').'>'.h($label).'</option>';$s.='</select></label><label>Zoeken<input name="q457" maxlength="80" value="'.h($search).'"></label><button>Zoeken</button></form>';
 $items=[];if($route==='mine'){$rows=rows("SELECT o.id,o.design FROM go_ccobjects262 o JOIN go_media415_instances m ON m.item_id COLLATE utf8mb4_unicode_ci=o.id COLLATE utf8mb4_unicode_ci WHERE o.owner=? AND m.kind='electro' ORDER BY m.created DESC LIMIT 500",[$u['id']]);foreach($rows as $r){$d=json_decode($r['design'],true,64,JSON_THROW_ON_ERROR);$items[]=['model'=>$d['media415']['model'],'instance'=>$d['media415'],'ref'=>'o-'.$r['id']];}}
 else foreach(el457Catalog() as $m)$items[]=['model'=>$m];
 $owned=[];foreach(rows("SELECT m.model,COUNT(*) n FROM go_media415_instances m JOIN go_ccobjects262 o ON o.id COLLATE utf8mb4_unicode_ci=m.item_id COLLATE utf8mb4_unicode_ci WHERE o.owner=? AND m.kind='electro' GROUP BY m.model",[$u['id']]) as $r)$owned[$r['model']]=(int)$r['n'];
 $items=array_values(array_filter($items,fn($a)=>($type===''||$a['model']['category']===$type)&&($search===''||mb_stripos($a['model']['title'],$search)!==false)));
 $page=max(1,min(max(1,(int)ceil(count($items)/24)),(int)($_GET['p457']??1)));$total=count($items);$s.='<p>'.$total.' resultaten · pagina '.$page.' / '.max(1,(int)ceil($total/24)).'</p><div class="el457-grid">';foreach(array_slice($items,($page-1)*24,24) as $a){$m=$a['model'];$s.='<article><small>'.h(el457Types()[$m['category']]).' · In bezit: '.($owned[$m['id']]??0).'</small><a href="'.h($m['art']['image']).'" data-el457-zoom><img src="'.h($m['art']['image']).'" alt="'.h($m['title']).'" width="640" height="480" loading="lazy"></a><h2>'.h($m['title']).'</h2><p>◆ '.(int)($a['instance']['grade']['points']??$m['points']).' '.(isset($a['instance'])?'exemplaarpunten':'basispunten').'</p><details><summary>Informatie & fotobron</summary>'.el457Details($m).'</details>'.(isset($a['ref'])?'<a class="el457-action" href="/index.php?vc415=object&amp;ref='.h($a['ref']).'">Bekijken, verkopen of ruilen</a>':'').'</article>';}$s.='</div><nav>';for($i=1;$i<=ceil($total/24);$i++)$s.='<a href="/index.php?'.h(http_build_query(['el457'=>$route,'type457'=>$type,'q457'=>$search,'p457'=>$i])).'">'.$i.'</a> ';return $s.'</nav></section>';
}
function el457Dispatch():bool{
 $route=$_GET['el457']??'';if(!is_string($route)||!in_array($route,['catalog','mine','admin','save'],true))return false;
 if(!empty($GLOBALS['el457dispatch']))return true;$GLOBALS['el457dispatch']=true;$u=user();if(!$u){header('Location: /account.php',true,303);exit;}
 if(!function_exists('hbObject325'))require_once __DIR__.'/collector325.php';if(!function_exists('ccMeta262'))require_once __DIR__.'/collection262.php';
 try{if($route==='save'){if(($_SERVER['REQUEST_METHOD']??'')!=='POST')fail('Gebruik POST.');csrf();if(($u['role']??'')!=='owner')fail('Alleen hoofdbeheer.');$price=filter_var($_POST['price']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>1000000]]);$daily=filter_var($_POST['daily']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>100]]);if($price===false||$daily===false)fail('Controleer prijs en daglimiet.');vc415Atomic(function()use($price,$daily){$j=vm415Job('electro',true);$s=$j['data'];$s['price']=$price;$s['daily']=$daily;$s['enabled']=($_POST['enabled']??'')==='1';vm415State('electro',$s);});audit($u['id'],'electronics457-settings','electro',['price'=>$price,'daily'=>$daily]);$_SESSION['el457notice']='Instellingen opgeslagen.';header('Location: /index.php?el457=admin',true,303);exit;}$GLOBALS['vc415panel']=el457Page($u,$route);}
 catch(GameError $e){$GLOBALS['vc415panel']='<section class="el457"><p role="alert">'.h($e->getMessage()).'</p><a href="/index.php?el457=catalog">Terug naar elektronica</a></section>';}
 return true;
}
